baseCss:
.la-page {
    background: #f8fafc;
    color: #0f172a;
    font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
.la-section {
    margin: 0 auto 24px;
    max-width: 960px;
    border: 1px solid #dbe4ee;
    border-radius: 14px;
    background: #ffffff;
    padding: 28px;
    box-shadow: 0 14px 38px rgba(15, 23, 42, 0.08);
}
.la-hero {
    border-color: #67e8f9;
    background: linear-gradient(135deg, #ecfeff 0%, #ffffff 58%, #f8fafc 100%);
    padding: 44px 32px;
}
.la-section .la-eyebrow {
    margin: 0 0 10px;
    color: #0e7490;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.16em;
    text-transform: uppercase;
}
.la-section h1,
.la-section h2,
.la-section h3 {
    margin: 0;
    color: #0f172a;
    line-height: 1.08;
}
.la-section h1 {
    max-width: 820px;
    font-size: clamp(36px, 6vw, 64px);
}
.la-section h2 {
    font-size: 28px;
}
.la-section p {
    color: #475569;
    font-size: 16px;
    line-height: 1.7;
}
.la-section ul {
    margin: 18px 0 0;
    padding-left: 20px;
}
.la-section li {
    margin: 8px 0;
    color: #334155;
}
.la-cta {
    display: inline-flex;
    margin-top: 14px;
    border-radius: 8px;
    background: #0891b2;
    color: #ffffff;
    font-weight: 700;
    padding: 14px 20px;
    text-decoration: none;
}
.la-cta-outline {
    background: transparent;
    color: #0e7490;
    box-shadow: inset 0 0 0 2px #0891b2;
}
.la-cta-wrap {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}
.la-section .la-cta-micro {
    margin: 8px 0 0;
    color: #64748b;
    font-size: 13px;
    line-height: 1.5;
}
.la-cta-sticky {
    margin-top: 16px;
}
.la-hero-with-image {
    display: grid;
    grid-template-columns: 1.1fr 1fr;
    align-items: center;
    gap: 32px;
}
.la-hero-media img {
    width: 100%;
    height: auto;
    border-radius: 12px;
    box-shadow: 0 20px 44px rgba(15, 23, 42, 0.14);
}
@media (max-width: 720px) {
    .la-cta-mobile-full {
        display: flex;
        width: 100%;
        box-sizing: border-box;
        justify-content: center;
        font-size: 18px;
        padding: 16px 20px;
    }
    .la-cta-sticky {
        position: fixed;
        left: 0;
        right: 0;
        bottom: 0;
        z-index: 50;
        margin: 0;
        padding: 10px 16px;
        background: #ffffff;
        box-shadow: 0 -4px 16px rgba(15, 23, 42, 0.12);
    }
    .la-cta-sticky .la-cta {
        margin-top: 0;
    }
    .la-page:has(.la-cta-sticky) {
        padding-bottom: 96px;
    }
    .la-hero-with-image {
        grid-template-columns: 1fr;
    }
}
.la-section.la-divider {
    height: 1px;
    min-height: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    background: #cbd5e1;
}
.la-image-text {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: 32px;
}
.la-image-text img {
    width: 100%;
    height: auto;
    border-radius: 12px;
}
.la-pricing {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
    margin-top: 18px;
}
.la-plan {
    border: 1px solid #dbe4ee;
    border-radius: 12px;
    padding: 20px;
    background: #f8fafc;
}
.la-faq-item {
    margin-top: 16px;
    padding-top: 16px;
    border-top: 1px solid #e2e8f0;
}
.la-faq-item h3 {
    font-size: 18px;
}
.la-cta.la-instagram {
    background: #0f172a;
}
@media (max-width: 720px) {
    .la-image-text {
        grid-template-columns: 1fr;
    }
}
.la-proof img,
.la-testimonial img {
    width: 100%;
    max-width: 480px;
    height: auto;
    border-radius: 10px;
    margin: 12px 0;
}
.la-testimonial {
    border-color: #fcd34d;
    background: #fffbeb;
}
.la-footer {
    border-color: #cbd5e1;
    background: #0f172a;
}
.la-footer h2,
.la-footer p {
    color: #f8fafc;
}
.la-hero-bg {
    position: relative;
    overflow: hidden;
    display: flex;
    align-items: center;
    min-height: 360px;
    background: #0f172a;
}
.la-hero-bg-img {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    z-index: 0;
}
.la-overlay {
    position: absolute;
    inset: 0;
    background: #0f172a;
    z-index: 1;
}
.la-overlay-20 {
    opacity: 0.2;
}
.la-overlay-40 {
    opacity: 0.4;
}
.la-overlay-60 {
    opacity: 0.6;
}
.la-hero-bg-content {
    position: relative;
    z-index: 2;
    max-width: 640px;
    padding: 48px 32px;
}
.la-hero-bg h1,
.la-hero-bg p {
    color: #ffffff;
}
.la-focus-top {
    object-position: center top;
}
.la-focus-center {
    object-position: center center;
}
.la-focus-bottom {
    object-position: center bottom;
}
.la-hero-top .la-hero-media img {
    max-height: 360px;
    object-fit: cover;
}
